// backend/routes/reports/render/route.ts
var RenderRequestSchema = external_exports.object({
  type: external_exports.enum(["invoice", "ledger", "voucher", "gstr"]),
  format: external_exports.enum(["html", "pdf"]).default("html"),
  data: external_exports.any()
});
async function POST14(req) {
  let browser = null;
  try {
    const body = await req.json();
    const result = RenderRequestSchema.safeParse(body);
    if (!result.success) {
      return new Response(JSON.stringify({ error: "Invalid request", details: result.error.issues }), {
        status: 400,
        headers: { "Content-Type": "application/json" }
      });
    }
    const { type, format, data } = result.data;
    let htmlContent = "";
    console.log(`[PDF] Generating HTML for type: ${type}`);
    switch (type) {
      case "invoice":
        htmlContent = renderInvoice(data);
        break;
      case "ledger":
        htmlContent = renderLedger(data);
        break;
      case "voucher":
        htmlContent = renderVoucher(data);
        break;
      case "gstr":
        htmlContent = renderGSTR(data);
        break;
    }
    if (format === "html") {
      return new Response(htmlContent, {
        headers: { "Content-Type": "text/html" }
      });
    }
    if (format === "pdf") {
      return new Response(JSON.stringify({ error: "Server-side PDF generation is disabled. Please use native print functionality." }), {
        status: 400,
        headers: { "Content-Type": "application/json" }
      });
    }
  } catch (error63) {
    console.error(`[PDF] ERROR:`, error63);
    return new Response(JSON.stringify({ error: "Internal Server Error" }), {
      status: 500,
      headers: { "Content-Type": "application/json" }
    });
  } finally {
    if (browser) {
      console.log(`[PDF] Closing browser`);
      try {
        await browser.close();
        console.log(`[PDF] Browser closed successfully`);
      } catch (closeError) {
        console.error(`[PDF] Error closing browser:`, closeError);
      }
    }
  }
}

